let tapPoint=null;
async function scan(source,width,height){if(busy)return;stopLive();const gen=++generation;busy=true;photo=true;results=[];q('aiScan').disabled=true;q('aiCancel').hidden=false;q('aiBack').hidden=true;q('aiNext').hidden=true;q('zoom').hidden=true;q('aiResult').textContent='';if(running&&!frozen)q('freeze').click();q('freeze').disabled=true;q('aiThreshold').disabled=true;const scale=Math.min(1,SHOT_MAX/Math.max(width,height));shot.width=Math.round(width*scale);shot.height=Math.round(height*scale);shot.getContext('2d').drawImage(source,0,0,shot.width,shot.height);shot.hidden=boxes.hidden=false;oc.clearRect(0,0,overlay.width,overlay.height);q('count').textContent='AI 분석';q('guide').textContent='촬영한 화면 분석 중 · 이동해도 사진은 유지됩니다';render();try{await load();if(gen!==generation)return;const regions=[[0,0,shot.width,shot.height]];if(shot.width>640||shot.height>640)for(const y of positions(shot.height))for(const x of positions(shot.width))regions.push([x,y,Math.min(640,shot.width),Math.min(640,shot.height)]);let all=[],done=0;const dots=spots(),total=regions.length+dots.length*ZOOM_TARGETS.length,begin=performance.now(),tick=label=>{const spent=(performance.now()-begin)/1000,left=done?Math.ceil(spent/done*(total-done)):0;status(`${label} ${done+1}/${total} · ${Math.round(spent)}초`+(left?` · 약 ${left}초 남음`:''))};for(let i=0;i<regions.length;i++,done++){if(gen!==generation)return;tick('모기 형태 분석');await new Promise(r=>setTimeout(r,30));all.push(...await infer(...regions[i]));}for(const m of dots){const mx=m.x+m.w/2,my=m.y+m.h/2;if(all.some(b=>near(b,mx,my,4))){done+=ZOOM_TARGETS.length;continue}for(const t of ZOOM_TARGETS){if(gen!==generation)return;tick('작은 점 확대 분석');await new Promise(r=>setTimeout(r,30));all.push(...(await zoomAt(mx,my,Math.max(m.w,m.h,6)*640/t)).filter(b=>fits(b,m)));done++}}if(gen!==generation)return;results=suppress(all);selected=0;render();status(results.length?`모기로 추정한 위치 ${results.length}곳 · 확대 화면으로 확인하세요`:'모기를 검출하지 못했습니다. 의심되는 점을 눌러 확대 분석하거나 더 가까이 찍어 보세요.');q('count').textContent='AI 추정 '+results.length;q('guide').textContent=results.length?'상자는 촬영 당시 위치 · 놓친 점은 눌러서 확대 분석':'의심되는 점을 누르면 확대 분석 · 미검출이 모기 없음은 아닙니다';q('aiBack').hidden=false;}catch(e){if(gen!==generation)return;status('AI 분석 실패: '+(e.message||'실행 메모리가 부족하거나 지원되지 않는 브라우저입니다.'));q('aiBack').hidden=false;q('guide').textContent='AI 분석에 실패했습니다 · 다시 촬영해 주세요';}finally{if(gen===generation){busy=false;q('aiThreshold').disabled=false;q('aiScan').disabled=false;q('aiCancel').hidden=true}}}
/* Tap a suspicious spot on the analyzed photo: snap to the dark spot under the finger and re-run the model on several enlarged crops of it.
   Enlarging a blank patch makes the model report noise as a mosquito, so a tap with no dark spot nearby is not analyzed. */
screen.addEventListener('click',async e=>{if(!photo||busy||e.target===q('zoom'))return;const r=screen.getBoundingClientRect(),scale=Math.min(r.width/shot.width,r.height/shot.height),x=(e.clientX-r.left-(r.width-shot.width*scale)/2)/scale,y=(e.clientY-r.top-(r.height-shot.height*scale)/2)/scale;if(x<0||y<0||x>shot.width||y>shot.height)return;const tol=Math.max(6,16/scale),half=Math.round(Math.max(80,tol*3)),x0=Math.max(0,Math.round(x-half)),y0=Math.max(0,Math.round(y-half)),spot=spots(x0,y0,Math.min(shot.width,Math.round(x+half))-x0,Math.min(shot.height,Math.round(y+half))-y0,50).filter(m=>near(m,x,y,tol)).sort((a,b)=>Math.hypot(a.x+a.w/2-x,a.y+a.h/2-y)-Math.hypot(b.x+b.w/2-x,b.y+b.h/2-y))[0];if(!spot){status('누른 위치에 뚜렷한 점이 없습니다 · 점 위를 정확히 누르거나 더 가까이 찍어 보세요');return}const gen=generation,mx=spot.x+spot.w/2,my=spot.y+spot.h/2,hits=[];busy=true;tapPoint={x:mx,y:my};q('aiBack').hidden=true;q('aiScan').disabled=true;q('aiThreshold').disabled=true;render();try{for(let i=0;i<TAP_TARGETS.length;i++){if(gen!==generation)return;status(`누른 점 확대 분석 ${i+1}/${TAP_TARGETS.length}`);await new Promise(r=>setTimeout(r,30));hits.push(...(await zoomAt(mx,my,Math.max(spot.w,spot.h,6)*640/TAP_TARGETS[i])).filter(b=>fits(b,spot)))}if(gen!==generation)return;if(hits.length){const best=hits.reduce((a,b)=>b.score>a.score?b:a);results=suppress(results.concat(hits));selected=Math.max(0,results.findIndex(b=>iou(b,best)>.35||contained(b,best)>.7));status(`누른 점에서 모기 추정 · 모델 점수 ${best.score.toFixed(2)}`)}else status('누른 점에서 모기를 찾지 못했습니다 · 더 가까이 찍어 보세요');q('count').textContent='AI 추정 '+results.length}catch(err){if(gen===generation)status('확대 분석 실패: '+(err.message||'다시 시도해 주세요'))}finally{if(gen===generation){busy=false;tapPoint=null;q('aiBack').hidden=false;q('aiScan').disabled=false;q('aiThreshold').disabled=false;render()}}});
q('aiScan').onclick=()=>{if(!running||demo||video.readyState<2){status('먼저 카메라 시작을 누르고 실제 벽·천장을 비춰 주세요.');return}if(photo){reset();status('카메라가 다시 켜졌습니다. 초점을 맞춘 뒤 정밀 촬영을 다시 누르세요.');return}scan(video,video.videoWidth,video.videoHeight)};
q('aiFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;reset();const url=URL.createObjectURL(f),img=new Image();img.onload=()=>{scan(img,img.naturalWidth,img.naturalHeight);URL.revokeObjectURL(url)};img.onerror=()=>{status('이 사진 형식을 읽을 수 없습니다. JPG 또는 PNG를 사용하세요.');URL.revokeObjectURL(url)};img.src=url;e.target.value=''};
